import { test, expect } from '@playwright/test';

test.describe('Export Records to CSV', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    await page.waitForLoadState('networkidle');
  });

  test('should display export button on records list page', async ({ page }) => {
    await expect(page.getByRole('button', { name: /export to csv/i })).toBeVisible();
  });

  test('should export records to CSV file', async ({ page, context }) => {
    // Listen for download event
    const downloadPromise = context.waitForEvent('download');

    // Click export button
    await page.getByRole('button', { name: /export to csv/i }).click();

    // Wait for download to complete
    const download = await downloadPromise;

    // Verify download filename
    expect(download.suggestedFilename()).toMatch(/records.*\.csv$/i);

    // Verify file path exists
    const path = await download.path();
    expect(path).toBeTruthy();
  });

  test('should export only selected records when records are selected', async ({ page, context }) => {
    // Select first record checkbox
    const firstCheckbox = page.getByRole('checkbox').first();
    await firstCheckbox.click();

    // Verify checkbox is checked
    await expect(firstCheckbox).toBeChecked();

    // Listen for download event
    const downloadPromise = context.waitForEvent('download');

    // Click export button
    await page.getByRole('button', { name: /export to csv/i }).click();

    // Wait for download
    const download = await downloadPromise;

    // Verify CSV file was downloaded
    expect(download.suggestedFilename()).toMatch(/records.*\.csv$/i);
  });

  test('should show success message after export', async ({ page, context }) => {
    // Listen for download
    const downloadPromise = context.waitForEvent('download');

    // Click export button
    await page.getByRole('button', { name: /export to csv/i }).click();

    // Wait for download to complete
    await downloadPromise;

    // Verify success message appears
    await expect(page.getByText(/export successful|records exported/i)).toBeVisible();
  });

  test('should disable export button when no records are available', async ({ page }) => {
    // Navigate to empty records page
    await page.goto('http://localhost:3000/records?empty=true');
    await page.waitForLoadState('networkidle');

    // Verify export button is disabled
    const exportButton = page.getByRole('button', { name: /export to csv/i });
    await expect(exportButton).toBeDisabled();
  });

  test('should export with correct CSV format and headers', async ({ page, context }) => {
    // Listen for download
    const downloadPromise = context.waitForEvent('download');

    // Click export button
    await page.getByRole('button', { name: /export to csv/i }).click();

    // Wait and get download
    const download = await downloadPromise;
    const path = await download.path();

    // Verify file exists and has content
    expect(path).toBeTruthy();

    // Verify filename contains expected pattern
    const filename = download.suggestedFilename();
    expect(filename).toMatch(/\.csv$/i);
    expect(filename.length).toBeGreaterThan(4);
  });
});
